function.arguments:
{"script":"var results = [];
// Each card has mntl-card-list-card--extendable_N-0 and matching meta containers
for (var n = 1; n <= 12; n++) {
  var titleEl = document.getElementById('mntl-card-list-card--extendable_' + n + '-0');
  var metaEl = document.getElementById('mntl-recipe-card-meta_' + n + '-0');
  var ratingEl = document.getElementById('mntl-recipe-star-rating_' + n + '-0');
  if (!titleEl || !ratingEl) continue;
  var rating = ratingEl.getAttribute('aria-label') || ratingEl.getAttribute('title') || null;
  var countEl = metaEl ? metaEl.querySelector('div[class*="rating-count"], div') : null;
  // Find the count number
  var countNumber = null;
  if (metaEl) {
    var divs = metaEl.querySelectorAll('div');
    for (var i = 0; i < divs.length; i++) {
      var t = divs[i].textContent.trim();
      if (/^[\d,]+$/.test(t)) { countNumber = t; break; }
    }
  }
  results.push({
    n: n,
    title: titleEl.textContent.trim().split(/\s{2,}|\n/).filter(function(s){return s && !/Save Recipe|BANANA/.test(s);}).pop(),
    rating: rating,
    count: countNumber,
    href: titleEl.href
  });
}
return results;"}

