{"script":"// Inspect the SVG rating container - check if there's a hidden rating value
var containers = document.querySelectorAll('[id^="mntl-recipe-star-rating_"]');
var result = [];
for (var i = 0; i < Math.min(containers.length, 4); i++) {
  var c = containers[i];
  // Look for data attributes
  var dataAttrs = {};
  for (var j = 0; j < c.attributes.length; j++) {
    var a = c.attributes[j];
    if (a.name.indexOf('data') === 0 || a.name === 'style') dataAttrs[a.name] = a.value;
  }
  // Look for child elements with rating info
  var innerText = c.textContent.trim();
  // Check if stars have any rating-related attribute (e.g., fill, color based on rating)
  var svgs = c.querySelectorAll('svg.icon-star');
  var starStyles = [];
  for (var k = 0; k < svgs.length; k++) {
    starStyles.push({
      cls: svgs[k].getAttribute('class'),
      fill: svgs[k].getAttribute('fill') || (svgs[k].style ? svgs[k].style.fill : ''),
      style: svgs[k].getAttribute('style') || ''
    });
  }
  result.push({ id: c.id, dataAttrs: dataAttrs, starStyles: starStyles, innerText: innerText });
}
return result;"}

