{"script":"var recipes = [];
var cards = document.querySelectorAll('a[id*="mntl-card-list-card--extendable"]');
for (var i = 0; i < cards.length; i++) {
  var card = cards[i];
  var parent = card.closest('div') || card.parentElement;
  // Walk up to find the card container
  var container = card.parentElement;
  // Get rating value from the aria-label or hidden text
  var ratingContainer = container.querySelector('[id*="mntl-recipe-star-rating"]');
  var ratingValue = null;
  if (ratingContainer) {
    var label = ratingContainer.getAttribute('aria-label') || '';
    var match = label.match(/(\d+\.?\d*)/);
    if (match) ratingValue = parseFloat(match[1]);
  }
  // Get count
  var countEl = container.querySelector('.mntl-recipe-card-meta__rating-count-number, [class*="rating-count-number"]');
  var countText = countEl ? countEl.textContent.trim() : null;
  var titleEl = container.querySelector('span');
  var title = titleEl ? titleEl.textContent.trim() : null;
  recipes.push({
    title: title,
    rating: ratingValue,
    ratingLabel: ratingContainer ? ratingContainer.getAttribute('aria-label') : null,
    count: countText,
    url: card.href
  });
}
return recipes;"}

